/*
 * prover.js
 *
 * Proves the claims of an exercise with an SMT solver, instead of testing
 * them on sample states. The claims are the same as those of the tester
 * (checker.js):
 *   - every line of every calculation, from the line before it;
 *   - every verification condition and every rule instance of the steps;
 *   - every check of the annotated program, generated by ivl.js: each
 *     link between two assertions, and for a loop the initialisation, the
 *     preservation and the conclusion.
 * When all the checks of the annotated program are proved, and it starts
 * with {P} and ends with {Q}, the triple of the exercise is proved.
 *
 * Every counterexample found by the solver is evaluated with the evaluator
 * of the site (logic.js). A counterexample in which the claim is not false
 * reveals an error in the prover, and is reported as such.
 */
(function (root) {
  'use strict';
  const HL = (root.HL = root.HL || {});
  const N = HL.N;

  // The verdict of one claim. expect is 'holds' or 'fails' (the exercise
  // says that the claim does not hold, and gives a counterexample).
  function verdict(r, expect) {
    if (r.status === 'proved') return expect === 'holds';
    if (r.status === 'refuted') return expect === 'fails' && r.confirmed !== false;
    return null;
  }

  // Evaluate "hyps ==> goal" in a state: false confirms a counterexample.
  function confirm(hyps, goal, state) {
    try {
      const f = hyps.length ? N.bin('==>', hyps.reduce((a, b) => N.bin('&&', a, b)), goal) : goal;
      return HL.truth(HL.evaluate(f, state));
    } catch (e) {
      return undefined;
    }
  }

  async function prove(solver, hyps, goal, opts) {
    let r = await HL.SMT.prove(solver, hyps, goal, opts);
    // With recursive definitions, the first answer can be a state that is
    // not a real counterexample, or no answer. A second search looks for a
    // counterexample among small numbers, with the definitions unfolded
    // further, so that they are known exactly on those numbers.
    if ((r.status === 'refuted' || r.status === 'unknown') && r.partial !== false) {
      const spurious = r.status === 'refuted' && confirm(hyps, goal, r.state) !== false;
      if (r.status === 'unknown' || spurious) {
        const r2 = await HL.SMT.prove(solver, hyps, goal, Object.assign({}, opts, { depth: 12, small: 10 }));
        if (r2.status === 'refuted' && confirm(hyps, goal, r2.state) === false) r = r2;
      }
    }
    if (r.status === 'refuted') {
      const v = confirm(hyps, goal, r.state);
      r.confirmed = v === false ? true : v === true ? false : null;
      if (r.confirmed === null && r.partial) {
        // The evaluator cannot compute the claim in that state (a sum over
        // more than 2000 numbers, for example), and the solver only knows a
        // few steps of the definitions: the state may not be a real
        // counterexample, so the claim is not decided.
        r.status = 'unknown';
        r.reason = 'Not decided: the solver gave a state that the site cannot evaluate, and it only unfolds the definitions of sum, prod, fib, fact and pow a few steps.';
      }
      if (r.confirmed === false) {
        // The claim holds in the state found by the solver. With recursive
        // definitions this is the limit of their unfolding: not decided.
        // Without them it would be an error of the prover.
        r.status = r.partial ? 'unknown' : 'error';
        r.reason = r.partial
          ? 'Not decided: the solver gave a state in which the claim holds, because it only unfolds the definitions of sum, prod, fib, fact and pow a few steps.'
          : 'Error of the prover: the solver gave a state in which the claim holds.';
      }
    }
    return r;
  }

  async function proveExercise(ex, solver, opts = {}) {
    const results = [];
    if (ex.errors.length || !ex.program || !ex.pre || !ex.post) {
      results.push({ group: 'Exercise', item: 'Reading the file', status: 'skip', ok: null, reason: 'The exercise has errors, so it was not proved.' });
      return results;
    }
    const choices = ex.choices && ex.choices.length ? ex.choices : [{ title: '', outcome: 'proves', steps: ex.steps }];
    for (const choice of choices) {
      await proveChoice(ex, choice, choices.length > 1 ? choice.title + ', ' : '', solver, opts, results);
      if (opts.onProgress) opts.onProgress(results);
    }
    return results;
  }

  async function proveChoice(ex, choice, prefix, solver, opts, results) {
    const slots = new Map([['P', ex.pre], ['Q', ex.post]]);
    const res = HL.Checker.resolver(ex, slots);
    const prepare = (f) => HL.Checker.prepare(f, res);
    const add = async (where, hyps, goal) => {
      const r = await prove(solver, hyps, goal, opts);
      const ok = verdict(r, where.expect);
      results.push(Object.assign({ ok }, where, r));
      if (opts.onProgress) opts.onProgress(results);
    };
    const skip = (where, reason) => results.push(Object.assign({ status: 'skip', ok: null, reason }, where));

    // 1. The claims of the steps.
    for (const step of choice.steps) {
      const group = prefix + 'Step ' + (step.number || step.index) + ': ' + step.title;
      for (const it of step.items) if (it.kind === 'set' && it.f) slots.set(it.name, it.f);
      const assume = step.assume ? prepare(step.assume) : { f: null };
      const H = assume.f ? [assume.f] : [];
      let calcNo = 0, vcNo = 0;
      for (const it of step.items) {
        if (it.kind === 'calc') {
          calcNo++;
          for (let j = 1; j < it.rows.length; j++) {
            const a = it.rows[j - 1];
            const b = it.rows[j];
            const where = { group, item: 'Calculation' + (calcNo > 1 ? ' ' + calcNo : '') + ', line ' + (j + 1), line: b.line, expect: 'holds', ref: b };
            if (!a.f || !b.f) { skip(where, 'One of the two lines could not be read.'); continue; }
            const pa = prepare(a.f);
            const pb = prepare(b.f);
            if (pa.skip || pb.skip) { skip(where, pa.skip || pb.skip); continue; }
            if (b.rel === 'eq') await add(where, H, N.bin('<=>', N.paren(pa.f), N.paren(pb.f)));
            else if (b.rel === 'imp') await add(where, H.concat([pa.f]), pb.f);
            else await add(where, H.concat([pb.f]), pa.f);
          }
        }
        if (it.kind === 'vc' || it.kind === 'instance') {
          const lines = it.kind === 'vc' ? [{ e: it, name: 'Verification condition ' + (++vcNo), expect: it.status }]
            : it.premises.map((p, j) => ({ e: p, name: 'Rule instance, premise ' + (j + 1), expect: 'holds' }))
              .concat(it.conclusion ? [{ e: it.conclusion, name: 'Rule instance, conclusion', expect: 'holds' }] : []);
          for (const { e, name, expect } of lines) {
            const where = { group, item: name, line: e.line, expect, ref: e };
            if (!e.node) { skip(where, 'The line could not be read.'); continue; }
            const p = HL.Checker.prepareLine(e.node, res);
            if (p.skip) { skip(where, p.skip); continue; }
            const node = p.node;
            if (node.k === 'triple') {
              let loops = false;
              HL.walkStmts(node.prog, (s) => { if (s.k === 'while') loops = true; });
              if (loops) { skip(where, 'A triple with a loop is proved through its invariant, in the annotated program.'); continue; }
              await add(where, H.concat([node.pre]), HL.wp(node.prog, node.post));
            } else {
              await add(where, H, node.f);
            }
          }
        }
      }
    }

    // 2. The checks of the annotated program, with the values of the slots
    // at the end of this choice.
    const allVars = new Set();
    HL.progVars(ex.program).forEach((v) => allVars.add(v));
    HL.freeVars(ex.pre).forEach((v) => allVars.add(v));
    HL.freeVars(ex.post).forEach((v) => allVars.add(v));
    let unresolved = null;
    const resolve = (a) => {
      const p = prepare(a.f);
      if (p.skip) { unresolved = p.skip; return null; }
      HL.freeVars(p.f).forEach((v) => allVars.add(v));
      return p.f;
    };
    // Resolve every assertion once first, so that allVars is complete.
    HL.walkAsserts(ex.program, (a) => resolve(a));
    const group = prefix + 'Annotated program';
    if (unresolved) {
      skip({ group, item: 'The checks of the annotated program', expect: 'holds' }, unresolved);
      return;
    }
    const outer = new Set([...HL.freeVars(ex.pre), ...HL.freeVars(ex.post)]);
    const { errors, checks } = HL.IVL.outlineChecks(ex.program, resolve, allVars, outer);
    errors.forEach((msg) => skip({ group, item: 'The annotated program', expect: 'holds' }, msg));
    let allProved = !errors.length;
    // A link may break when the triple is not valid, when the choice does
    // not lead to a proof, or in an example of a rule that does not derive
    // the triple.
    const expectBroken = ex.verdict === 'invalid' || choice.outcome === 'fails' || ex.derived === false;
    for (const c of checks) {
      const where = { group, item: c.name, line: ex.programLine, expect: 'holds' };
      const r = await prove(solver, c.hyps, c.goal, opts);
      if (r.status !== 'proved') allProved = false;
      const out = Object.assign({ ok: verdict(r, 'holds') }, where, r);
      if (r.status === 'refuted' && expectBroken && r.confirmed !== false) {
        out.status = 'expected';
        out.ok = null;
        out.reason = ex.verdict === 'invalid'
          ? 'This check fails, which is expected: the exercise states that the triple is not valid.'
          : choice.outcome === 'fails' ? 'This check fails, which is expected: this choice does not lead to a proof.'
            : 'This check fails, which is expected: the rule does not derive this triple.';
      }
      results.push(out);
      if (opts.onProgress) opts.onProgress(results);
    }

    // 3. The triple of the exercise.
    const asserts = [];
    HL.walkAsserts(ex.program, (a) => asserts.push(a));
    const top = ex.program.items || [];
    const first = top.find((x) => x.k === 'assert');
    const last = [...top].reverse().find((x) => x.k === 'assert');
    const framed = first && last && first.slot === 'P' && last.slot === 'Q';
    if (!expectBroken) {
      results.push({
        group, item: 'The triple {P} program {Q}', expect: 'holds', line: ex.programLine,
        status: allProved && framed ? 'proved' : 'skip', ok: allProved && framed ? true : null,
        reason: allProved && framed ? 'Every check of the annotated program is proved, and it starts with {P} and ends with {Q}.'
          : !framed ? 'The annotated program does not start with {P} and end with {Q}.' : 'Not every check of the annotated program is proved.'
      });
    }
  }

  HL.Prover = { proveExercise, prove };
})(typeof window !== 'undefined' ? window : globalThis);
